        /// A joined provider failure before the Git commit boundary is a known
        /// failed run. It retains the same checkout and allows the existing
        /// explicit Retry action; only an unconfirmed lifecycle/Git outcome is
        /// held as RecoveryRequired.
        #[tokio::test]
        async fn a_terminal_provider_failure_is_retryable_without_losing_its_checkout() {
            let w = world(Class::Created).await;
            git_in(&w.repo, &["config", "user.email", "t@example.com"]);
            git_in(&w.repo, &["config", "user.name", "T"]);
            {
                let _agent = crate::test_helpers::FakeProgram::install(
                    "claude",
                    "cat >/dev/null; echo 'the model is unavailable' >&2; exit 1",
                )
                .await;
                assert_eq!(
                    w.executor.spawn_task_execution(w.task_id, None).await,
                    Ok(true)
                );
                assert_eq!(settled(&w).await.status, TaskStatus::Error);
            }
            let failed = kinds(&w.on_disk());
            assert!(
                matches!(&failed[..], [
                    ActivityKind::RunStarted { run: 1, .. },
                    ActivityKind::RunFailed { run: Some(1), reason },
                ] if reason.contains("the model is unavailable")),
                "{failed:?}"
            );

            assert!(w.on_disk().worker_handoff.is_none());
            assert!(w.on_disk().worker_recovery_refusal().is_none());
            assert_eq!(w.on_disk().status, TaskStatus::Error);
            assert!(
                !w.on_disk()
                    .activity
                    .iter()
                    .any(|e| matches!(e.kind, ActivityKind::RunResult { .. })),
                "a failed run records no result"
            );
            assert!(matches!(failed.as_slice(), [
                ActivityKind::RunStarted { run: 1, .. },
                ActivityKind::RunFailed { run: Some(1), reason },
            ] if reason.contains("the model is unavailable")));
            assert!(
                w.on_disk().worktree_path.is_some(),
                "the failed run's Task Checkout remains attached"
            );

            {
                let mut tasks = w.executor.tasks.write().await;
                let task = tasks.get_mut(&w.task_id).unwrap();
                task.status = TaskStatus::InProgress;
                task.phase = TaskPhase::Idle;
                let board: Vec<_> = tasks
                    .values()
                    .filter(|task| task.project_id == w.project_id)
                    .cloned()
                    .collect();
                w.executor
                    .storage
                    .save_project_tasks(w.project_id, &board)
                    .expect("persist the explicit retry decision");
            }
            let _agent = crate::test_helpers::FakeProgram::install(
                "claude",
                "cat >/dev/null; printf '%s\\n' '{\"type\":\"system\",\"subtype\":\"init\",\"session_id\":\"s-worker\",\"permissionMode\":\"auto\"}'; printf 'retry work\\n' > retry-output.txt; printf '%s\\n' '{\"type\":\"result\",\"subtype\":\"success\",\"is_error\":false,\"result\":\"done\"}'",
            )
            .await;
            assert_eq!(
                w.executor.spawn_task_execution(w.task_id, None).await,
                Ok(true)
            );
            assert_eq!(settled(&w).await.status, TaskStatus::AiReview);
            assert_eq!(
                kinds(&w.on_disk())
                    .iter()
                    .filter(|kind| matches!(kind, ActivityKind::RunStarted { .. }))
                    .count(),
                2
            );
        }

        #[tokio::test]
        async fn direct_execution_cannot_bypass_a_persisted_started_handoff() {
            let w = world(Class::Created).await;
            {
                let mut tasks = w.executor.tasks.write().await;
                let task = tasks.get_mut(&w.task_id).unwrap();
                task.status = TaskStatus::InProgress;
                task.worker_handoff = Some(crate::domain::task::WorkerHandoff {
                    review_mode: Default::default(),
                    task_id: w.task_id,
                    project_id: w.project_id,
                    repository_id: None,
                    run: Some(1),
                    branch: Some(WorktreeManager::branch_for_task(w.task_id)),
                    start_head: Some(w.main_tip.clone()),
                    acceptance: None,
                    stage: crate::domain::task::WorkerHandoffStage::Started {},
                    review_mode_unproven: false,
                });
                let board: Vec<_> = tasks
                    .values()
                    .filter(|task| task.project_id == w.project_id)
                    .cloned()
                    .collect();
                w.executor
                    .storage
                    .save_project_tasks(w.project_id, &board)
                    .expect("persist the interrupted start");
            }
            let before = w.on_disk();
            let error = w
                .executor
                .execute_task(w.task_id)
                .await
                .expect_err("direct execution must honor the recovery gate");
            assert!(
                error.contains("unresolved Worker recovery evidence"),
                "{error}"
            );
            assert_eq!(
                w.executor.tasks.read().await[&w.task_id].status,
                TaskStatus::InProgress
            );
            assert_eq!(
                kinds(&w.executor.tasks.read().await[&w.task_id]),
                kinds(&before),
                "refusal must not mutate Task history"
            );
            assert!(!w.executor.is_task_running(w.task_id).await);
        }

        /// Every run's end on the timeline has its start there too.
        fn every_end_has_its_start(kinds: &[ActivityKind]) {
            for kind in kinds {
                if let ActivityKind::RunCompleted { run }
                | ActivityKind::RunFailed { run: Some(run), .. } = kind
                {
                    assert!(
                        kinds.iter().any(
                            |k| matches!(k, ActivityKind::RunStarted { run: r, .. } if r == run)
                        ),
                        "run {run} ended without starting: {kinds:?}"
                    );
                }
            }
        }

        /// A start that cannot be recorded launches no agent and numbers no
        /// run, so the next start is run 1 and its end has its start.
        #[tokio::test]
        async fn a_start_that_cannot_be_recorded_numbers_no_run() {
            let w = world(Class::Created).await;
            git_in(&w.repo, &["config", "user.email", "t@example.com"]);
            git_in(&w.repo, &["config", "user.name", "T"]);
            let agent = fake_agent().await;
            let Some(unwritable) = crate::test_helpers::UnwritableDir::new(&w.tasks_dir()) else {
                eprintln!("skipped: the tasks directory stays writable (running as root?)");
                return;
            };

            let refused = w.executor.spawn_task_execution(w.task_id, None).await;

            assert!(refused.is_err(), "{refused:?}");
            assert!(
                !agent_invoked(&agent).await,
                "no agent may start without a recorded run"
            );
            let (memory, disk) = (w.in_memory().await, w.on_disk());
            assert_eq!(memory.activity, disk.activity);
            assert_eq!((&memory.status, &memory.phase), (&disk.status, &disk.phase));
            assert!(
                !memory
                    .activity
                    .iter()
                    .any(|e| matches!(e.kind, ActivityKind::RunStarted { .. }))
            );
            assert!(w.executor.run_tools.lock().unwrap().is_empty());
            drop(unwritable);
            drop(agent);

            w.restart().await;
            let _agent = crate::test_helpers::FakeProgram::install(
                "claude",
                "cat >/dev/null; printf '%s\\n' '{\"type\":\"system\",\"subtype\":\"init\",\"session_id\":\"s-worker\",\"permissionMode\":\"auto\"}'; printf 'work\\n' > agent_work.txt; \
                 printf '%s\\n' '{\"type\":\"result\",\"subtype\":\"success\",\"is_error\":false,\"result\":\"done\"}'",
            )
            .await;
            assert_eq!(
                w.executor.spawn_task_execution(w.task_id, None).await,
                Ok(true)
            );
            assert_eq!(settled(&w).await.status, TaskStatus::AiReview);
            let recorded = kinds(&w.on_disk());
            assert_eq!(
                recorded,
                [
                    ActivityKind::RunStarted {
                        run: 1,
                        addressing_feedback: false
                    },
                    ActivityKind::RunCompleted { run: 1 },
                    ActivityKind::RunResult {
                        run: 1,
                        result: slashit_activity::RunResult::Available {
                            text: "done".into(),
                        },
                    },
                ]
            );
            every_end_has_its_start(&recorded);
        }

        /// The provider and Git commit finish, but the exact commit evidence
        /// cannot be written. SlashIt refuses to guess the SHA and later holds
        /// the Task for inspection without replaying coding work.
        #[tokio::test]
        async fn a_finish_that_cannot_be_recorded_is_not_published() {
            let recording = Arc::new(crate::events::RecordingEventSink::new());
            let w = world_with(test_executor_with_events(recording.clone()), Class::Created).await;
            git_in(&w.repo, &["config", "user.email", "t@example.com"]);
            git_in(&w.repo, &["config", "user.name", "T"]);
            let gate = tempfile::tempdir().unwrap();
            let (started, go) = (gate.path().join("started"), gate.path().join("go"));
            let tool = serde_json::json!({"type": "assistant", "message": {"content": [
                {"type": "tool_use", "id": "t", "name": "Bash", "input": {"command": "cargo test"}}
            ]}});
            let _agent = crate::test_helpers::FakeProgram::install(
                "claude",
                &format!(
                    "cat >/dev/null; printf '%s\\n' '{{\"type\":\"system\",\"subtype\":\"init\",\"session_id\":\"s-worker\",\"permissionMode\":\"auto\"}}'; {}printf 'work\\n' > agent_work.txt; : > '{}'; \
                     while [ ! -e '{}' ]; do sleep 0.05; done; \
                     printf '%s\\n' '{{\"type\":\"result\",\"subtype\":\"success\",\"is_error\":false,\"result\":\"done\"}}'",
                    stream(&[tool]),
                    started.display(),
                    go.display(),
                ),
            )
            .await;

            assert_eq!(
                w.executor.spawn_task_execution(w.task_id, None).await,
                Ok(true)
            );
            for _ in 0..200 {
                if started.exists() {
                    break;
                }
                tokio::time::sleep(std::time::Duration::from_millis(50)).await;
            }
            assert!(started.exists(), "the agent ran");
            let unwritable = crate::test_helpers::UnwritableDir::new(&w.tasks_dir());
            std::fs::write(&go, b"").unwrap();
            let Some(unwritable) = unwritable else {
                w.end_run().await;
                eprintln!("skipped: the tasks directory stays writable (running as root?)");
                return;
            };

            let ended = |recording: &crate::events::RecordingEventSink| {
                recording.recorded().into_iter().find(|(name, payload)| {
                    name == "agent-event"
                        && matches!(
                            payload.get("type").and_then(|v| v.as_str()),
                            Some("completed" | "error")
                        )
                })
            };
            let mut ending = None;
            for _ in 0..200 {
                ending = ended(&recording);
                if ending.is_some() {
                    break;
                }
                tokio::time::sleep(std::time::Duration::from_millis(50)).await;
            }
            let (_, ending) = ending.expect("the run announced how it ended");

            assert_eq!(
                ending.get("type").and_then(|v| v.as_str()),
                Some("error"),
                "{ending}"
            );
            assert!(
                ending
                    .to_string()
                    .contains("recording its exact completion evidence"),
                "{ending}"
            );
            let (memory, disk) = (w.in_memory().await, w.on_disk());
            assert_eq!(
                memory.status,
                TaskStatus::InProgress,
                "{:?}",
                memory.error_message
            );
            assert_eq!(
                (
                    &memory.status,
                    &memory.phase,
                    memory.phase_progress,
                    memory.overall_progress,
                    &memory.error_message
                ),
                (
                    &disk.status,
                    &disk.phase,
                    disk.phase_progress,
                    disk.overall_progress,
                    &disk.error_message
                ),
                "the board shows exactly what the file has"
            );
            assert_eq!(memory.activity, disk.activity);
            assert_eq!(
                kinds(&disk),
                [ActivityKind::RunStarted {
                    run: 1,
                    addressing_feedback: false
                }]
            );
            let handoff = disk
                .worker_handoff
                .as_ref()
                .expect("durable start record remains");
            assert!(matches!(
                handoff.stage,
                crate::domain::task::WorkerHandoffStage::Started {}
            ));
            let tip = git_in(
                &w.repo,
                &[
                    "rev-parse",
                    &format!("refs/heads/{}", handoff.branch.as_deref().unwrap()),
                ],
            );
            assert_ne!(
                tip,
                handoff.start_head.as_deref().unwrap(),
                "the checkout moved, but its commit cannot be attributed"
            );
            drop(unwritable);
            w.end_run().await;
            w.executor.check_and_execute().await;
            let recovered = w.on_disk();
            assert_eq!(recovered.status, TaskStatus::Error);
            assert!(matches!(
                recovered.worker_handoff.as_ref().unwrap().stage,
                crate::domain::task::WorkerHandoffStage::RecoveryRequired {
                    observed_commit: None,
                    ..
                }
            ));
            assert!(recovered.needs_you(false).is_some());
            assert!(!recovered.activity.iter().any(|entry| matches!(
                entry.kind,
                ActivityKind::RunCompleted { .. } | ActivityKind::RunFailed { .. }
            )));
            let retry = w.executor.spawn_task_execution(w.task_id, None).await;
            assert_eq!(
                retry,
                Ok(false),
                "no coding Worker can replay the uncertain effect"
            );
        }

